import { describe, expect, it } from "vitest";
import {
  LAUNCHD_LABEL,
  parseLaunchctlPrint,
  parseLaunchdProgramArguments,
  renderLaunchdPlist,
  xmlEscape,
} from "./launchd.js";

const PLIST = `<?xml version="1.0" encoding="UTF-8"?>
<!DOCTYPE plist PUBLIC "-//Apple//DTD PLIST 1.0//EN" "http://www.apple.com/DTDs/PropertyList-1.0.dtd">
<!-- Generated by ocw-runtime service install; re-run it instead of editing. -->
<plist version="1.0">
<dict>
  <key>Label</key>
  <string>org.ocw.runtime</string>
  <key>ProgramArguments</key>
  <array>
    <string>/opt/homebrew/bin/node</string>
    <string>/Users/alice/.ocw/runtime/current/ocw-runtime.mjs</string>
    <string>run</string>
  </array>
  <key>RunAtLoad</key>
  <true/>
  <key>KeepAlive</key>
  <dict>
    <key>SuccessfulExit</key>
    <false/>
  </dict>
  <key>ProcessType</key>
  <string>Standard</string>
  <key>WorkingDirectory</key>
  <string>/Users/alice</string>
  <key>EnvironmentVariables</key>
  <dict>
    <key>PATH</key>
    <string>/opt/homebrew/bin:/usr/bin:/bin</string>
    <key>OCW_RUNTIME_HOST</key>
    <string>service</string>
  </dict>
  <key>StandardOutPath</key>
  <string>/Users/alice/.ocw/logs/runtime.log</string>
  <key>StandardErrorPath</key>
  <string>/Users/alice/.ocw/logs/runtime.log</string>
</dict>
</plist>
`;

const base = {
  nodePath: "/opt/homebrew/bin/node",
  bundlePath: "/Users/alice/.ocw/runtime/current/ocw-runtime.mjs",
  workingDirectory: "/Users/alice",
  path: "/opt/homebrew/bin:/usr/bin:/bin",
  logFile: "/Users/alice/.ocw/logs/runtime.log",
};

describe("renderLaunchdPlist (07.12, D-04, PD-11, RESEARCH Pitfall 9)", () => {
  it("equals the snapshot", () => {
    expect(LAUNCHD_LABEL).toBe("org.ocw.runtime");
    expect(renderLaunchdPlist(base)).toBe(PLIST);
  });

  it("keeps a stopped agent stopped (KeepAlive on failure only) and is not throttled", () => {
    const plist = renderLaunchdPlist(base);
    expect(plist).toContain("<key>SuccessfulExit</key>\n    <false/>");
    expect(plist).toContain("<key>ProcessType</key>\n  <string>Standard</string>");
    expect(plist).not.toMatch(/TOKEN|SECRET|service\.env|Sockets/i);
  });

  it("names OCW_HOME only when it is not the default", () => {
    const plist = renderLaunchdPlist({ ...base, ocwHome: "/Volumes/data/ocw" });
    expect(plist).toContain("    <key>OCW_HOME</key>\n    <string>/Volumes/data/ocw</string>\n");
  });

  it("XML-escapes every value", () => {
    expect(xmlEscape(`a&b<c>d"e'f`)).toBe("a&amp;b&lt;c&gt;d&quot;e&apos;f");
    const home = `/Users/a&b <c> "d" 'e'`;
    const plist = renderLaunchdPlist({
      ...base,
      bundlePath: `${home}/.ocw/runtime/current/ocw-runtime.mjs`,
      workingDirectory: home,
      logFile: `${home}/.ocw/logs/runtime.log`,
    });
    expect(plist).toContain(
      "<string>/Users/a&amp;b &lt;c&gt; &quot;d&quot; &apos;e&apos;/.ocw/runtime/current/ocw-runtime.mjs</string>",
    );
    expect(plist).not.toContain("<c>");
    expect(parseLaunchdProgramArguments(plist)).toEqual({
      nodePath: "/opt/homebrew/bin/node",
      bundlePath: `${home}/.ocw/runtime/current/ocw-runtime.mjs`,
    });
  });

  it("refuses control characters (not representable in XML 1.0)", () => {
    expect(() => xmlEscape("a\u0001b")).toThrow(/control character/);
    expect(() => renderLaunchdPlist({ ...base, workingDirectory: "/Users/a\nb" })).toThrow(
      /control character/,
    );
  });
});

describe("parseLaunchctlPrint (07.12, PD-11)", () => {
  it("reads the state and pid of the service", () => {
    const out = [
      "gui/501/org.ocw.runtime = {",
      "\tactive count = 1",
      "\tpath = /Users/alice/Library/LaunchAgents/org.ocw.runtime.plist",
      "\tstate = running",
      "",
      "\tprogram = /opt/homebrew/bin/node",
      "\tpid = 4242",
      "\tlast exit code = (never exited)",
      "}",
    ].join("\n");
    expect(parseLaunchctlPrint(out)).toEqual({ state: "running", pid: 4242 });
  });

  it("has no pid when the agent is waiting", () => {
    expect(parseLaunchctlPrint("gui/501/org.ocw.runtime = {\n\tstate = not running\n}")).toEqual({
      state: "not running",
      pid: null,
    });
    expect(parseLaunchctlPrint("")).toEqual({ state: null, pid: null });
  });
});
